package solution

import (
	"strconv"
	"testing"
)

func TestRenderBindingsLinesSortedAndQuoted(t *testing.T) {
	values := map[string]string{
		"z9":       "line\nquote\"",
		"_first":   "snowman ☃",
		"Alpha":    "",
	}
	got, err := RenderBindings(values, FormatLines)
	if err != nil {
		t.Fatalf("RenderBindings returned error: %v", err)
	}
	want := "Alpha = " + strconv.Quote("") + "\n" +
		"_first = " + strconv.Quote("snowman ☃") + "\n" +
		"z9 = " + strconv.Quote("line\nquote\"") + "\n"
	if got != want {
		t.Fatalf("lines = %q, want %q", got, want)
	}
	again, err := RenderBindings(values, FormatLines)
	if err != nil || again != got {
		t.Fatalf("second call = (%q, %v), want deterministic %q", again, err, got)
	}
}

func TestRenderBindingsJSONSortedCompactAndQuoted(t *testing.T) {
	values := map[string]string{"b": "雪", "a": "line\n\"q\""}
	got, err := RenderBindings(values, FormatJSON)
	if err != nil {
		t.Fatalf("RenderBindings returned error: %v", err)
	}
	want := `{"a":"line\n\"q\"","b":"雪"}` + "\n"
	if got != want {
		t.Fatalf("JSON = %q, want %q", got, want)
	}
}

func TestRenderBindingsEmptyAndNilMaps(t *testing.T) {
	for _, values := range []map[string]string{nil, {}} {
		lines, err := RenderBindings(values, FormatLines)
		if err != nil || lines != "" {
			t.Fatalf("empty lines = (%q, %v)", lines, err)
		}
		json, err := RenderBindings(values, FormatJSON)
		if err != nil || json != "{}\n" {
			t.Fatalf("empty JSON = (%q, %v)", json, err)
		}
	}
}

func TestRenderBindingsRejectsInvalidIdentifiers(t *testing.T) {
	for _, key := range []string{"", "1name", "has-dash", "has space", "é", "a.b"} {
		got, err := RenderBindings(map[string]string{key: "value"}, FormatLines)
		if err == nil || got != "" {
			t.Fatalf("invalid key %q returned (%q, %v)", key, got, err)
		}
	}
	for _, key := range []string{"a", "Z9", "_", "_a2"} {
		if _, err := RenderBindings(map[string]string{key: "value"}, FormatLines); err != nil {
			t.Fatalf("valid key %q rejected: %v", key, err)
		}
	}
}

func TestRenderBindingsRejectsUnsupportedFormatAndDoesNotMutateInput(t *testing.T) {
	values := map[string]string{"b": "two", "a": "one"}
	got, err := RenderBindings(values, OutputFormat(99))
	if err == nil || got != "" {
		t.Fatalf("unsupported format returned (%q, %v)", got, err)
	}
	if len(values) != 2 || values["a"] != "one" || values["b"] != "two" {
		t.Fatalf("input map was mutated: %#v", values)
	}
	if _, err := RenderBindings(values, FormatJSON); err != nil {
		t.Fatal(err)
	}
	if len(values) != 2 || values["a"] != "one" || values["b"] != "two" {
		t.Fatalf("input map was mutated after valid render: %#v", values)
	}
}

